export const zOutputData = z.object({
    data: zDataKind.nullable(),
    message: z.string(),
    result: zOutputResult,
    status: zStatus
});

/**
 * CliOutput
 *
 * The format for all messages written to stdout by the CLI
 */
export const zCliOutput = z.union([
    zOutputData.and(z.object({
        'output-kind': z.literal('output-data')
    })),
    zStatusUpdateData.and(z.object({
        'output-kind': z.literal('status-update')
    })),
    zNotification.and(z.object({
        'output-kind': z.literal('notification')
    }))
]);
